import test from 'node:test';
import assert from 'node:assert/strict';
import { createHmac } from 'node:crypto';
import { Readable } from 'node:stream';
import { createApp, MAX_BODY_BYTES, REPLAY_WINDOW_MS } from '../src/app.js';
import { createMemoryState } from '../src/state.js';

const secret = 'synthetic-unit-test-secret-only';
const time = Date.parse('2026-10-25T12:00:00.000Z');
const raid = { subscription: { type: 'channel.raid', version: '1' }, event: {
  from_broadcaster_user_id: '123', to_broadcaster_user_id: '456', viewers: 12,
} };
function signed({ body = raid, rawBody, id = 'test-event-1', timestamp = new Date(time).toISOString(), type = 'notification' } = {}) {
  const bytes = rawBody ?? Buffer.from(JSON.stringify(body));
  const signature = createHmac('sha256', secret).update(id).update(timestamp).update(bytes).digest('hex');
  return { method: 'POST', path: '/eventsub', rawBody: bytes, headers: {
    'twitch-eventsub-message-id': id, 'twitch-eventsub-message-timestamp': timestamp,
    'twitch-eventsub-message-signature': `sha256=${signature}`, 'twitch-eventsub-message-type': type,
  } };
}
function app(options = {}) { return createApp({ secret, now: () => time, ...options }); }

test('health is available without a webhook secret', async () => {
  const response = await createApp().dispatch({ method: 'GET', path: '/health' });
  assert.equal(response.status, 200);
  assert.deepEqual(JSON.parse(response.body), { status: 'ok' });
});
test('valid raid starts a local 90-second ritual', async () => {
  const instance = app();
  assert.equal((await instance.dispatch(signed())).status, 204);
  assert.deepEqual(instance.state.getRitual('456'), {
    eventId: 'test-event-1', incomingBroadcasterId: '123', hostBroadcasterId: '456',
    startedAt: time, endsAt: time + 90000,
  });
});
test('HMAC uses original whitespace and bytes', async () => {
  const request = signed({ rawBody: Buffer.from(JSON.stringify(raid, null, 2)) });
  assert.equal((await app().dispatch(request)).status, 204);
  request.rawBody = Buffer.from(JSON.stringify(raid));
  assert.equal((await app().dispatch(request)).status, 403);
});
test('forged and malformed signatures are rejected without state changes', async () => {
  for (const signature of ['sha256=' + '0'.repeat(64), 'sha256=abc', 'sha256=' + 'g'.repeat(64), '', ['sha256=abc']]) {
    const instance = app();
    const request = signed();
    request.headers['twitch-eventsub-message-signature'] = signature;
    assert.equal((await instance.dispatch(request)).status, 403);
    assert.equal(instance.state.getRitual('456'), undefined);
  }
});
test('tampered body, message id and timestamp fail authentication', async () => {
  for (const mutate of [
    req => { req.rawBody = Buffer.from('{}'); },
    req => { req.headers['twitch-eventsub-message-id'] = 'changed'; },
    req => { req.headers['twitch-eventsub-message-timestamp'] = '2026-10-25T11:59:59Z'; },
  ]) {
    const request = signed(); mutate(request);
    assert.equal((await app().dispatch(request)).status, 403);
  }
});
test('stale, future and malformed signed timestamps fail', async () => {
  for (const timestamp of [new Date(time - REPLAY_WINDOW_MS - 1).toISOString(), new Date(time + 1).toISOString(), 'invalid', '2026-10-25']) {
    assert.equal((await app().dispatch(signed({ timestamp }))).status, 403);
  }
  assert.equal((await app().dispatch(signed({ timestamp: new Date(time - REPLAY_WINDOW_MS).toISOString() }))).status, 204);
});
test('duplicate delivery acknowledges without restarting ritual', async () => {
  let clock = time;
  const instance = app({ now: () => clock });
  const request = signed();
  assert.equal((await instance.dispatch(request)).status, 204);
  clock += 5000;
  assert.equal((await instance.dispatch(request)).status, 204);
  assert.equal(instance.state.getRitual('456').startedAt, time);
});
test('concurrent duplicates are accepted once by shared memory state', async () => {
  const memory = createMemoryState();
  let accepted = 0;
  const state = { accept(input) { const outcome = memory.accept(input); if (outcome === 'accepted') accepted++; return outcome; } };
  const instances = [app({ state }), app({ state })];
  const responses = await Promise.all(Array.from({ length: 40 }, (_, i) => instances[i % 2].dispatch(signed())));
  assert.ok(responses.every(response => response.status === 204));
  assert.equal(accepted, 1);
});
test('signed challenge is returned verbatim and retryable, without ritual', async () => {
  const instance = app();
  const request = signed({ type: 'webhook_callback_verification', body: { challenge: 'challenge-text' } });
  for (let i = 0; i < 2; i++) {
    const response = await instance.dispatch(request);
    assert.equal(response.status, 200);
    assert.equal(response.body, 'challenge-text');
    assert.equal(response.type, 'text/plain; charset=utf-8');
  }
  assert.equal(instance.state.getRitual('456'), undefined);
  request.headers['twitch-eventsub-message-signature'] = 'sha256=' + '0'.repeat(64);
  assert.equal((await instance.dispatch(request)).status, 403);
});
test('malformed JSON, invalid UTF-8, invalid schema and missing challenge fail', async () => {
  for (const rawBody of [Buffer.from('{'), Buffer.from([0xff]), Buffer.from('null'), Buffer.from('[]')]) {
    assert.equal((await app().dispatch(signed({ rawBody }))).status, 400);
  }
  for (const body of [{}, { ...raid, event: {} }, { ...raid, event: { ...raid.event, viewers: -1 } }, { subscription: { type: 'other' } }]) {
    assert.equal((await app().dispatch(signed({ body }))).status, 400);
  }
  assert.equal((await app().dispatch(signed({ type: 'webhook_callback_verification', body: {} }))).status, 400);
});
test('oversized signed body rejected before parsing or state mutation', async () => {
  const instance = app();
  assert.equal((await instance.dispatch(signed({ rawBody: Buffer.alloc(MAX_BODY_BYTES + 1, 32) }))).status, 413);
  assert.equal(instance.state.getRitual('456'), undefined);
});
test('HTTP stream adapter enforces body limit across chunks without listening', async () => {
  const request = Readable.from([Buffer.alloc(MAX_BODY_BYTES), Buffer.from('x')]);
  Object.assign(request, { method: 'POST', url: '/eventsub', headers: {} });
  const response = { writeHead(status) { this.status = status; }, end(body) { this.body = body; } };
  await app().handler(request, response);
  assert.equal(response.status, 413);
});
test('HTTP stream adapter preserves signed raw bytes and handles health', async () => {
  for (const input of [signed(), { method: 'GET', path: '/health', headers: {}, rawBody: Buffer.alloc(0) }]) {
    const request = Readable.from([input.rawBody.subarray(0, 5), input.rawBody.subarray(5)]);
    Object.assign(request, { method: input.method, url: input.path, headers: input.headers });
    const response = { writeHead(status) { this.status = status; }, end(body) { this.body = body; } };
    await app().handler(request, response);
    assert.equal(response.status, input.path === '/health' ? 200 : 204);
  }
});
test('memory state is isolated by default; bounded capacity fails safely', async () => {
  const instance = app({ state: createMemoryState({ maxEvents: 1 }) });
  assert.equal((await instance.dispatch(signed())).status, 204);
  assert.equal((await instance.dispatch(signed({ id: 'second' }))).status, 503);
  assert.equal(app().state.getRitual('456'), undefined);
  const snapshot = instance.state.getRitual('456'); snapshot.endsAt = 0;
  assert.equal(instance.state.getRitual('456').endsAt, time + 90000);
});
test('expired dedupe entries release capacity', () => {
  const state = createMemoryState({ maxEvents: 1 });
  assert.equal(state.accept({ id: 'a', now: time, expiresAt: time + 1 }), 'accepted');
  assert.equal(state.accept({ id: 'b', now: time + 2, expiresAt: time + 3 }), 'accepted');
});
test('revocation acknowledges without creating a ritual', async () => {
  const instance = app();
  assert.equal((await instance.dispatch(signed({ type: 'revocation', body: { subscription: { type: 'channel.raid' } } }))).status, 204);
  assert.equal(instance.state.getRitual('456'), undefined);
});
test('configuration, routes and static assets', async () => {
  assert.equal((await createApp().dispatch(signed())).status, 503);
  assert.equal((await app().dispatch({ method: 'GET', path: '/eventsub' })).status, 405);
  assert.equal((await app().dispatch({ method: 'GET', path: '/missing' })).status, 404);
  for (const path of ['/', '/overlay', '/relic.svg', '/style.css']) {
    assert.equal((await app().dispatch({ method: 'GET', path })).status, 200);
  }
});
# Raid Relic

A raid-only traveling community relic. This first increment is a dependency-free local prototype, authored by Codex in the single conversation recorded in [CODEX_SESSION.md](CODEX_SESSION.md). Resume that thread for all future code and documentation work.

## Setup and tests

Use Node.js 22 or newer (the initial checks ran on Node 24). No npm dependencies, credentials, cloud SDK, or OAuth setup are required for tests.

```sh
npm test
```

The tests use synthetic signing secrets, an injected clock and memory state, and simulated HTTP streams. They do not bind a listening socket or contact Twitch. The application server was not started during this increment.

For a later, explicitly authorized local preview, copy `.env.example` to `.env`, replace the secret placeholder locally, and use `node --env-file=.env src/server.js`. The default port is **5191**; `PORT` can override it. `npm start` reads already exported environment variables and does not load `.env` automatically. Never commit local env files. The supplied client ID `6ggythtvgo572dxu8jo4xoaqtn37ix` is public configuration, not a credential, and is unused by this increment. Do not provide OAuth or cloud credentials yet.

Routes: `GET /health` returns JSON health; `POST /eventsub` accepts webhook messages; `/` is the static Atlas; `/overlay` is the static overlay. The original compass/crystal SVG is in `public/relic.svg`. Both views explicitly display prototype status and have no live data or countdown.

## Webhook boundary

The signature is HMAC-SHA256 over message ID + original timestamp + exact raw request body bytes. The implementation validates the signature encoding and compares fixed-length digests with `timingSafeEqual` before JSON parsing. It rejects bodies over 64 KiB, malformed JSON/UTF-8, invalid raid fields, and unsupported notification subscriptions. Raid notifications require `channel.raid` version `1`.

Authenticated timestamps may be at most ten minutes old; future timestamps are rejected, so the receiving clock must be accurate. Timestamp checks happen before deduplication. Repeated authenticated message IDs are acknowledged with 204 without restarting a ritual. Entries remain through their signature acceptance window; memory capacity returns 503 rather than discarding unexpired IDs. Signed verification challenges return their exact challenge text, including on retries. Signed revocations are acknowledged but do not yet update subscription lifecycle state. Missing webhook configuration fails closed with 503; health remains available.

A valid raid notification records a **local 90-second ritual starting at receipt processing time**, never a Twitch-synchronized window. There is no claim endpoint in this increment. A future claim must prove participation from **both incoming raiders and host chat**; a raid event alone does not prove individual viewer membership. OAuth, identity rules, chat collection, and abuse controls need design and verification before claims exist.

`createApp({ secret, state, now })` supports injection without opening a server. `dispatch` accepts raw buffers and lowercase HTTP headers; `handler` adapts Node HTTP streams and enforces the limit during collection. The memory adapter's `accept({ id, expiresAt, now, raid })` returns `accepted`, `duplicate`, or `full`. Insertion and ritual mutation are synchronous within one process; concurrent duplicate tests share the same state. `getRitual` returns a snapshot, not a durable or live state API. Expired entries are lazily pruned on acceptance. No secret or request-body logging is implemented.

## Architecture and deployment boundary

The target is **Cloud Run with minimum instances zero and Firestore**, not Cloudflare. A later Firestore adapter must transactionally deduplicate the event and create/update its ritual together, with expiry cleanup and bounded retention. An instance restart currently loses all memory; separate instances do not share it. This adapter is only for local tests/prototyping and must be replaced before deployment.

Store deadlines as timestamps. Do not rely on a background timer while Cloud Run is scaled to zero; evaluate deadlines when processing requests. Later overlays need an authenticated state transport and consistent persistent reads. Cloud Run cold starts and delivery latency do not make the local ritual synchronized with Twitch.

The owner reports project `raid-relic-hackathon` exists with billing intentionally disabled. Deployment is blocked pending the owner. No GCP resources or billing were inspected or changed. No deployment configuration is included, and scale-to-zero does not promise zero cost. Do not link billing or deploy in this increment.

## Verified locally versus pending

Automated tests cover health, raw-byte signature preservation, valid/tampered/forged signatures, malformed signature lengths, stale/future/invalid timestamps, duplicate and concurrent deliveries, exact retryable challenge responses, malformed/oversized bodies, invalid UTF-8 and schemas, streaming body limits, adapter capacity/expiry/isolation, revocation acknowledgement, and static asset loading. Initial verification: `npm test` passed; `node test/app.test.js` explicitly reported **17 tests passing, zero failures** on Node 24.22.1. The test runner in this environment summarizes `npm test` as one passing test file; the direct invocation exposes the individual node:test results. These are local implementation checks, not Twitch certification.

Pending: Firestore transactions, durable journey/ownership history, claim rules, OAuth, chat bot, token handling, subscription registration/revocation lifecycle, live webhook delivery, browser/OBS validation, accessibility review, and deployment. No live Twitch or Devpost interaction has occurred. No claims or successful handoffs are represented by the skeleton.

Before any live integration, verify against current official Twitch documentation: EventSub `channel.raid` version and conditions (incoming host filter versus outgoing broadcaster), subscription authorization and transport requirements, signature/timestamp/retry behavior, and callback challenge expectations. No current scope requirements were verified online in this increment. Raid EventSub permission requirements must be checked independently of chat. For the future EventSub chat bot path, investigate `user:read:chat`, `user:write:chat`, `user:bot`, and `channel:bot`, their token types, broadcaster grants/moderator alternatives, and whether writing chat is necessary. These are candidates to verify, not an approved scope set. Request only the minimum scopes for the chosen design after verification.

## How we used Codex

Codex is the sole code author in the original thread and created the HTTP boundary, injectable memory adapter, synthetic test cases, original SVG and static pages, and documentation. No other thread or subagent was created. Local automated verification is kept separate from pending integration claims. The first attempt was blocked by the workspace sandbox before any files were written; work resumed in the same thread after the operator fixed it. Raw rollout evidence/backups are ignored and must not be committed. See [AGENTS.md](AGENTS.md) for ongoing constraints.

